import { refresh } from 'next/cache'

let notificationsEnabled = false

export async function getNotificationPreference(): Promise<boolean> {
  return notificationsEnabled
}

export async function toggleNotificationPreference() {
  'use server'
  notificationsEnabled = !notificationsEnabled
  refresh()
}

export default async function Home() {
  const isEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <div>
        <p>Notifications: {isEnabled ? 'On' : 'Off'}</p>
        <form action={toggleNotificationPreference}>
          <button type="submit">
            {isEnabled ? 'Turn Off' : 'Turn On'} Notifications
          </button>
        </form>
      </div>
    </main>
  )
}

'use server'

import { refresh } from 'next/cache'

let notificationsEnabled = false

export async function getNotificationPreference(): Promise<boolean> {
  return notificationsEnabled
}

export async function toggleNotificationPreference() {
  notificationsEnabled = !notificationsEnabled
  refresh()
}

import {
  getNotificationPreference,
  toggleNotificationPreference,
} from './actions'

export default async function Home() {
  const isEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <div>
        <p>Notifications: {isEnabled ? 'On' : 'Off'}</p>
        <form action={toggleNotificationPreference}>
          <button type="submit">
            {isEnabled ? 'Turn Off' : 'Turn On'} Notifications
          </button>
        </form>
      </div>
    </main>
  )
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

import { connection } from 'next/server'
import {
  getNotificationPreference,
  toggleNotificationPreference,
} from './actions'

export default async function Home() {
  await connection()
  const isEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <div>
        <p>Notifications: {isEnabled ? 'On' : 'Off'}</p>
        <form action={toggleNotificationPreference}>
          <button type="submit">
            {isEnabled ? 'Turn Off' : 'Turn On'} Notifications
          </button>
        </form>
      </div>
    </main>
  )
}
